Definition cfg_hdr0 (ioc : Z) : svch := mkSVC AVP_CONFIG_SVC 0 0 ioc 0 P_A_DESTROY_ALLOC_CONFIG.

Definition msc_segB_post (sp gp tp s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A r ioc lo : Z) (s4v s3v s2v s1v s0v rav : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 s3 s4 t3 t4 t5 t6 m' j4,
    ms' = MS (mkR (Z_to_bv 64 P_A_MSC_RET2) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 r) (Z_to_bv 64 A) (Z_to_bv 64 r) (Z_to_bv 64 (bv_unsigned sp + -64)) (Z_to_bv 64 A) a3 a4 a5 a6 a7
                  (Z_to_bv 64 (A + 40)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_DO_ADD_SERVICE) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + 56)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells asegs m' (bv_unsigned sp + -64) (msc_frame (Z_to_bv 64 AL_TYPEID_CONFIG) (Z_to_bv 64 0) s4v s3v s2v s1v s0v rav)
    /\ rw_cells asegs m' A (SvcHdrCells (cfg_hdr0 ioc))
    /\ rw_cells asegs m' (A + 48) [C4 (wz 4294967295); CB 4 j4]
    /\ ACONST m'.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma msc_segB : asan_memset_stmt ->
  forall (pcv sp gp tp t0 t1 t2 s1x a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) fc (m : mem) (A r hintp ioc lo shi : Z) (j16 junkB : list byte),
  (pcv = Z_to_bv 64 P_A_MSC_RET1 \/ pcv = ret_pc (Z_to_bv 64 P_A_MSC_RET1)) ->
  rw_cells asegs m (bv_unsigned sp + -64) [CB 16 j16; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
  rw_cells asegs m A [CB 56 junkB] ->
  ro_cells asegs m hintp [C4 (wz 4294967295)] -> bv_unsigned sp <= hintp -> hintp + 4 <= shi ->
